syntax = "proto3";

package orderflow;

option go_package = "github.com/your-org/orderflow/gen/proto;orderflowpb";

// ---------------------------------------------------------------------------
// Shared types
// ---------------------------------------------------------------------------

message Money {
  int64  amount_cents = 1;  // smallest currency unit (e.g. cents for USD)
  string currency     = 2;  // ISO 4217 three-letter code, e.g. "USD"
}

message OrderItem {
  string sku         = 1;
  int32  quantity    = 2;
  Money  unit_price  = 3;
}

// ---------------------------------------------------------------------------
// OrderService — owned by order-service (:50051)
// ---------------------------------------------------------------------------

service OrderService {
  rpc CreateOrder  (CreateOrderRequest)  returns (CreateOrderResponse);
  rpc GetOrder     (GetOrderRequest)     returns (GetOrderResponse);
  rpc ListOrders   (ListOrdersRequest)   returns (ListOrdersResponse);
  rpc CancelOrder  (CancelOrderRequest)  returns (CancelOrderResponse);
}

// CreateOrder

message CreateOrderRequest {
  string            client_order_id = 1;  // caller-generated idempotency key
  string            customer_id     = 2;
  repeated OrderItem items          = 3;
  Money             total           = 4;
}

message CreateOrderResponse {
  string order_id = 1;
  string status   = 2;  // "PENDING"
}

// GetOrder

message GetOrderRequest {
  string order_id = 1;
}

message GetOrderResponse {
  string            order_id        = 1;
  string            client_order_id = 2;
  string            customer_id     = 3;
  string            status          = 4;
  Money             total           = 5;
  optional string   payment_id      = 6;
  string            created_at      = 7;  // RFC 3339
  string            updated_at      = 8;  // RFC 3339
  repeated OrderItem items          = 9;
}

// ListOrders

message ListOrdersRequest {
  string customer_id = 1;
  int32  page_size   = 2;  // max 100; default 20
  string page_token  = 3;  // opaque cursor; empty for first page
}

message ListOrdersResponse {
  repeated GetOrderResponse orders         = 1;
  string                    next_page_token = 2;  // empty when no more pages
}

// CancelOrder

message CancelOrderRequest {
  string order_id = 1;
  string reason   = 2;
}

message CancelOrderResponse {
  string order_id = 1;
  string status   = 2;  // "CANCELLED"
}

// ---------------------------------------------------------------------------
// PaymentService — owned by payment-service (:50052)
// ---------------------------------------------------------------------------

service PaymentService {
  rpc ChargePayment  (ChargePaymentRequest)  returns (ChargePaymentResponse);
  rpc RefundPayment  (RefundPaymentRequest)  returns (RefundPaymentResponse);
  rpc GetPayment     (GetPaymentRequest)     returns (GetPaymentResponse);
}

// ChargePayment

message ChargePaymentRequest {
  string order_id           = 1;
  string customer_id        = 2;
  Money  amount             = 3;
  string idempotency_key    = 4;  // recommended: "{order_id}_charge"
}

message ChargePaymentResponse {
  string payment_id         = 1;
  string stripe_payment_id  = 2;
  string status             = 3;  // "CAPTURED" | "PENDING" (async capture)
}

// RefundPayment

message RefundPaymentRequest {
  string payment_id      = 1;
  Money  amount          = 2;  // partial refund supported; omit for full refund
  string idempotency_key = 3;
}

message RefundPaymentResponse {
  string payment_id        = 1;
  string stripe_refund_id  = 2;
  string status            = 3;  // "REFUNDED" | "PARTIAL_REFUND"
}

// GetPayment

message GetPaymentRequest {
  string payment_id = 1;
}

message GetPaymentResponse {
  string payment_id        = 1;
  string order_id          = 2;
  string stripe_payment_id = 3;
  string status            = 4;
  Money  amount            = 5;
  string created_at        = 6;  // RFC 3339
  string updated_at        = 7;  // RFC 3339
}

